/**
 * REOS translations shared by the web app, the mobile app and Laravel (emails).
 *
 * - `src/locales/en.json` is the source. Every key must exist in every other
 *   language with the same `{{placeholders}}`; `pnpm --filter @reos/i18n check`
 *   enforces it in CI.
 * - Laravel gets flattened copies (`apps/platform/lang/{locale}.json`, with
 *   `:placeholders`), generated by `pnpm --filter @reos/i18n build`.
 * - Keys are type-checked: `t('appearance.theme')` compiles, a typo doesn't.
 */
import i18next, { type i18n as I18n } from 'i18next';
import en from './locales/en.json' with { type: 'json' };
import es from './locales/es.json' with { type: 'json' };

export const supportedLocales = ['en', 'es'] as const;
export type Locale = (typeof supportedLocales)[number];
export const defaultLocale: Locale = 'en';

/** Each language's name in its own language, so people can always find theirs. */
export const localeNames: Record<Locale, string> = { en: 'English', es: 'Español' };

export const resources = {
  en: { translation: en },
  es: { translation: es },
} as const;

export function isLocale(value: unknown): value is Locale {
  return typeof value === 'string' && (supportedLocales as readonly string[]).includes(value);
}

/** Picks a supported locale from a tag like `es-MX` or `en_US`; falls back to English. */
export function toLocale(tag: string | null | undefined): Locale {
  const base = (tag ?? '').toLowerCase().split(/[-_]/)[0];
  return isLocale(base) ? base : defaultLocale;
}

/**
 * Creates an initialised i18next instance (synchronous, resources bundled).
 * React apps pass it to `I18nextProvider`.
 */
export function createI18n(locale: Locale = defaultLocale): I18n {
  const instance = i18next.createInstance();

  void instance.init({
    resources,
    lng: locale,
    fallbackLng: defaultLocale,
    supportedLngs: [...supportedLocales],
    interpolation: { escapeValue: false }, // React escapes output itself
    returnNull: false,
    initAsync: false,
  });

  return instance;
}

declare module 'i18next' {
  interface CustomTypeOptions {
    defaultNS: 'translation';
    resources: (typeof resources)['en'];
  }
}
